import UIKit

/// The Byline Times masthead (TIMES in red), stored in the code so the project needs no resource files.
enum MastheadArt {
    static let image: UIImage? = {
        guard let data = Data(base64Encoded: base64) else { return nil }
        return UIImage(data: data, scale: 3)
    }()

    private static let base64 = ""
}
